"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant1 from "./components/empty-states/variants/02-search";
const variants = {"search": Variant1};
export interface ArtemisEmptyStatesProps { className?: string; variant?: "search"; }
export function ArtemisEmptyStates({ className, variant = "search" }: ArtemisEmptyStatesProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { useEffect, useState } from "react";
import { ARTEMIS_EASE_IN_OUT, ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
const LINE_OFFSETS = [0, -12, 10] as const;
const LINE_WIDTHS = ["80%", "58%", "72%"] as const;
function SearchLines({ reduce, stage, embedded }: {
    reduce: boolean | null;
    stage: number;
    embedded: boolean;
}) {
    return (<div className="art:absolute art:inset-x-5 art:top-6 art:space-y-5">
      {LINE_WIDTHS.map((width, index) => (<motion.div key={width} className="art:h-px art:origin-left art:bg-foreground" style={{ width, transitionDuration: embedded ? "0s" : undefined }} initial={reduce ? { opacity: 0.28, scaleX: 1 } : { opacity: 0, scaleX: 0 }} animate={reduce ? { opacity: 0.28, scaleX: 1, x: LINE_OFFSETS[index] } : stage >= 1 ? { opacity: stage >= 3 ? 0.28 : 0.62, scaleX: 1, x: stage >= 3 ? LINE_OFFSETS[index] : 0 } : undefined} transition={reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_PANEL, delay: index * 0.05 }}/>))}
    </div>);
}
export default function EmptyStatesSearch() {
    const reduce = useReducedMotion();
    const embedded = false;
    const [stage, setStage] = useState(0);
    useEffect(() => {
        if (reduce) {
            setStage(3);
            return;
        }
        const timers = [80, 220, 420].map((delay, index) => window.setTimeout(() => setStage(index + 1), delay));
        return () => timers.forEach(timer => window.clearTimeout(timer));
    }, [reduce]);
    return (<>
      <section className="art:mx-auto art:flex art:w-full art:max-w-[520px] art:flex-col art:items-center art:justify-center art:text-center art:text-foreground">
        <div aria-hidden="true" className="art:relative art:mb-6 art:h-36 art:w-64">
          <SearchLines reduce={reduce} stage={stage} embedded={embedded}/>
          <motion.div style={{ transitionDuration: embedded ? "0s" : undefined }} className="art:absolute art:left-1/2 art:top-1/2 art:grid art:size-20 art:-translate-x-1/2 art:-translate-y-1/2 art:place-items-center art:rounded-full art:border art:border-foreground art:bg-background" initial={reduce ? { opacity: 1, scale: 1 } : { opacity: 0, scale: 0.8 }} animate={reduce ? { opacity: 1, scale: 1, x: 0 } : stage >= 2 ? { opacity: 1, scale: 1, x: [-42, 42] } : undefined} transition={reduce ? { duration: 0 } : {
            opacity: { duration: 0.15, ease: "easeOut" },
            scale: ARTEMIS_SPRING_PANEL,
            x: { duration: 1.4, ease: ARTEMIS_EASE_IN_OUT, repeat: Infinity, repeatType: "mirror" },
        }}>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-search art:size-7" aria-hidden="true">
              <path d="m21 21-4.34-4.34"/>
              <circle cx="11" cy="11" r="8"/>
            </svg>
          </motion.div>
          <motion.span style={{ transitionDuration: embedded ? "0s" : undefined }} className="art:absolute art:right-2 art:top-1 art:grid art:size-7 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground" initial={reduce ? { opacity: 1, scale: 1, rotate: 0 } : { opacity: 0, scale: 0.6, rotate: -20 }} animate={reduce || stage >= 3 ? { opacity: 1, scale: 1, rotate: 0 } : undefined} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL}>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-x art:size-3.5" aria-hidden="true">
              <path d="M18 6 6 18"/>
              <path d="m6 6 12 12"/>
            </svg>
          </motion.span>
        </div>
        <h2 className="art:text-balance art:tracking-[-0.03em] art:text-4xl art:font-medium">
          {"No matches"}
        </h2>
        <p className="art:mt-2 art:max-w-xs art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
          {"Try another phrase or clear your filters."}
        </p>
        <motion.button type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-1.5 art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-4 art:h-9 art:rounded-full" tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS}>
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-rotate-ccw art:size-3.5" aria-hidden="true">
            <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/>
            <path d="M3 3v5h5"/>
          </svg>
          {"Reset search"}
        </motion.button>
      </section>
    </>);
}
